const u=document.querySelector(".lheader"),c=()=>u.classList.toggle("is-scrolled",window.scrollY>8);window.addEventListener("scroll",c,{passive:!0});c();const s=document.querySelector("[data-filters]");if(s){const l=[...s.querySelectorAll("button")],a=[...document.querySelectorAll("[data-kind]")],d=document.querySelector("[data-filter-status]");s.addEventListener("click",i=>{const e=i.target.closest("button");if(!e)return;const o=e.dataset.filter;l.forEach(t=>t.setAttribute("aria-pressed",String(t===e)));let n=0;a.forEach(t=>{const r=o==="all"||t.dataset.kind===o;t.hidden=!r,r&&(n+=1)}),d.textContent=`Показано концептов: ${n}`})}
